import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';
import io from 'socket.io-client';
import './App.css';

// Server URL
const SERVER_URL = 'http://localhost:3001';

function App() {
    const [sessionId, setSessionId] = useState(null);
    const [inputValue, setInputValue] = useState('');
    const [messages, setMessages] = useState([]);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState(null);
    const [browserImage, setBrowserImage] = useState(null);
    const [previewVisible, setPreviewVisible] = useState(true);
    // Add state for status messages
    const [statusMessages, setStatusMessages] = useState([]);
    const messagesEndRef = useRef(null);

    // Initialize session
    useEffect(() => {
        const initSession = async () => {
            try {
                // Check server status first
                const statusResponse = await axios.get(`${SERVER_URL}/status`);
                console.log("Server status:", statusResponse.data);

                // Get a new session ID
                const sessionResponse = await axios.post(`${SERVER_URL}/session`);
                if (sessionResponse.data.success) {
                    setSessionId(sessionResponse.data.sessionId);
                    setError(null);
                } else {
                    setError(`Error: ${sessionResponse.data.error}`);
                }
            } catch (err) {
                console.error('Error initializing session:', err);
                setError(`Error initializing session: ${err.message}`);

                // Try the alternate API path
                try {
                    const sessionResponse = await axios.post(`/api/session`);
                    if (sessionResponse.data.success) {
                        window.useDirectConnection = false;
                        setSessionId(sessionResponse.data.sessionId);
                        setError(null);
                    }
                } catch (fallbackErr) {
                    setError(`Failed to initialize session. Please ensure the server is running.`);
                }
            }
        };

        initSession();
    }, []);

    // Socket connection
    useEffect(() => {
        let socket;

        const connectSocket = () => {
            console.log("Connecting to socket...");
            socket = io(SERVER_URL, {
                reconnectionAttempts: 5,
                reconnectionDelay: 1000,
                transports: ['websocket', 'polling']
            });

            socket.on('connect', () => {
                console.log('Socket connected!');
                // Add a status message when connected
                addStatusMessage('system', 'Connected to server');
            });

            socket.on('connect_error', (error) => {
                console.error('Socket connection error:', error);
                addStatusMessage('error', `Connection error: ${error.message}`);
            });

            socket.on('reconnect_attempt', (attemptNumber) => {
                console.log(`Attempting to reconnect (${attemptNumber}/5)...`);
                addStatusMessage('system', `Reconnecting (attempt ${attemptNumber}/5)...`);
            });

            socket.on('browser-screenshot', (data) => {
                console.log('Received screenshot:', data.event);
                if (data.image) {
                    const imageUrl = `data:image/png;base64,${data.image}`;
                    setBrowserImage(imageUrl);
                    // Add status for screenshot event
                    addStatusMessage('info', `Screenshot received (${data.event})`);
                }
            });

            // Add listener for status updates from the server
            socket.on('status-update', (data) => {
                console.log('Status update:', data);
                addStatusMessage(getStatusType(data.event), data.message);
            });

            socket.on('error', (error) => {
                console.error('Socket error:', error);
                addStatusMessage('error', `Socket error: ${error}`);
            });

            socket.on('disconnect', (reason) => {
                console.log(`Socket disconnected: ${reason}`);
                addStatusMessage('system', `Disconnected: ${reason}`);
            });
        };

        connectSocket();

        return () => {
            if (socket) {
                socket.disconnect();
            }
        };
    }, []);

    // Helper function to add status messages with a timestamp
    const addStatusMessage = (type, text) => {
        const now = new Date();
        const timeString = now.toLocaleTimeString();
        setStatusMessages(prev => {
            // Keep only the most recent 10 messages
            const newMessages = [...prev, { type, text, time: timeString }];
            if (newMessages.length > 10) {
                return newMessages.slice(newMessages.length - 10);
            }
            return newMessages;
        });
    };

    // Helper to determine status type classes
    const getStatusType = (event) => {
        switch (event) {
            case 'error': return 'error';
            case 'thinking': return 'processing';
            case 'user-message': return 'user';
            case 'ai-response': return 'assistant';
            case 'tool-call': return 'tool';
            case 'response-complete': return 'success';
            default: return 'info';
        }
    };

    // Scroll to bottom of messages
    useEffect(() => {
        scrollToBottom();
    }, [messages]);

    const scrollToBottom = () => {
        messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    };

    const handleSendMessage = async (e) => {
        e.preventDefault();

        if (!inputValue.trim()) return;
        if (!sessionId) {
            setError('Session not initialized. Please try again.');
            return;
        }

        // Add user message to state immediately
        const userMessage = { role: 'user', content: inputValue };
        setMessages([...messages, userMessage]);
        setInputValue('');
        setLoading(true);
        setError(null);

        try {
            const endpoint = window.useDirectConnection
                ? `${SERVER_URL}/chat/${sessionId}`
                : `/api/chat/${sessionId}`;

            console.log(`Sending message to ${endpoint}`);
            const response = await axios.post(endpoint, {
                message: inputValue
            }, {
                timeout: 30000 // Longer timeout for chat requests
            });

            if (response.data.success) {
                // Get all messages from the response
                const allMessages = response.data.messages;
                setMessages(allMessages);
            } else {
                setError(`Error: ${response.data.error}`);
            }
        } catch (err) {
            console.error('Error sending message:', err);
            setError(`Error sending message: ${err.message}`);
            // Try the alternative endpoint if we get an error
            if (!window.useDirectConnection) {
                try {
                    console.log("Trying direct connection as fallback...");
                    const response = await axios.post(`${SERVER_URL}/chat/${sessionId}`, {
                        message: inputValue
                    }, {
                        timeout: 30000
                    });

                    if (response.data.success) {
                        // Get all messages from the response
                        const allMessages = response.data.messages;
                        setMessages(allMessages);
                        // Remember that direct connection works for future requests
                        window.useDirectConnection = true;
                        console.log("Switched to direct connection mode");
                        setError(null);
                    } else {
                        setError(`Error: ${response.data.error}`);
                    }
                } catch (fallbackErr) {
                    console.error('Fallback error:', fallbackErr);
                    setError(`Error sending message: ${err.message}. Fallback also failed.`);
                }
            }
        } finally {
            setLoading(false);
        }
    };

    // Add a function to request a screenshot
    const requestScreenshot = async () => {
        try {
            console.log("Requesting screenshot...");
            setError(null);
            const endpoint = window.useDirectConnection
                ? `${SERVER_URL}/screenshot`
                : '/api/screenshot';

            await axios.get(endpoint);
            console.log("Screenshot requested successfully");
        } catch (err) {
            console.error("Error requesting screenshot:", err);
            setError("Failed to request screenshot: " + err.message);
        }
    };

    const togglePreview = () => {
        setPreviewVisible(!previewVisible);
    };

    return (
        <div className="app-container">
            <header className="app-header">
                <h1>OpenAI MCP Client</h1>
                <button
                    className="toggle-preview-button"
                    onClick={togglePreview}
                >
                    {previewVisible ? 'Hide Preview' : 'Show Preview'}
                </button>
            </header>

            <main className="main-content">
                <div className="chat-section">
                    <div className="chat-container">
                        {messages.filter(msg => ['user', 'assistant'].includes(msg.role)).map((message, index) => (
                            <div key={index} className={`message ${message.role}`}>
                                <div className="message-role">{message.role}</div>
                                <div className="message-content">{message.content}</div>
                            </div>
                        ))}
                        {error && (
                            <div className="message error">
                                <div className="message-role">Error</div>
                                <div className="message-content">{error}</div>
                            </div>
                        )}
                        {loading && (
                            <div className="message loading">
                                <div className="message-content">
                                    <div className="loading-spinner"></div>
                                </div>
                            </div>
                        )}
                        <div ref={messagesEndRef} />
                    </div>

                    <form className="input-container" onSubmit={handleSendMessage}>
                        <input
                            type="text"
                            value={inputValue}
                            onChange={(e) => setInputValue(e.target.value)}
                            placeholder="Type your message..."
                            className="message-input"
                            disabled={loading || !sessionId}
                        />
                        <button
                            type="submit"
                            className="send-button"
                            disabled={loading || !sessionId || !inputValue.trim()}
                        >
                            Send
                        </button>
                    </form>
                </div>

                {previewVisible && (
                    <div className="preview-section">
                        <h2 className="preview-title">
                            Browser Preview
                            <button
                                onClick={requestScreenshot}
                                className="refresh-preview-button"
                                disabled={!sessionId}
                            >
                                Refresh Preview
                            </button>
                        </h2>
                        <div className="browser-preview">
                            {browserImage ? (
                                <img src={browserImage} alt="Browser preview" className="browser-image" />
                            ) : (
                                <div className="no-preview">
                                    No browser activity yet
                                </div>
                            )}
                        </div>

                        {/* Add status log section below the preview */}
                        <div className="status-log">
                            <h3>Status Log</h3>
                            <div className="status-messages">
                                {statusMessages.length === 0 ? (
                                    <div className="status-message info">
                                        <span className="status-time">--:--:--</span>
                                        <span className="status-text">Waiting for activity...</span>
                                    </div>
                                ) : (
                                    statusMessages.map((status, index) => (
                                        <div key={index} className={`status-message ${status.type}`}>
                                            <span className="status-time">{status.time}</span>
                                            <span className="status-text">{status.text}</span>
                                        </div>
                                    ))
                                )}
                            </div>
                        </div>
                    </div>
                )}
            </main>
        </div>
    );
}

export default App;
